'use strict';
const RULES='overdrive-2',STATE_KEY='overdrive2248-state-v2',RECORDS_KEY='overdrive2248-records-v2';
const modes={rogue:{name:'ローグライト'},normal:{name:'通常'},score60:{name:'スコアタ 1分',limit:60000},score600:{name:'スコアタ 10分',limit:600000},tile11:{name:'タイルTA 2048',target:11},tile20:{name:'タイルTA 2²⁰',target:20},tile50:{name:'タイルTA 2⁵⁰',target:50},tile100:{name:'タイルTA 2¹⁰⁰',target:100}};
let rngDeal=1,rngRescue=2,run={mode:'normal',seed:'',moves:0,actions:[],status:'playing',elapsed:0},startedMono=0,normalSave=null,rogueSave=null,records=[],recordTab='history',pendingFinish=false;
const encode=v=>JSON.stringify(v,(_,x)=>typeof x==='bigint'?x.toString():x);
function readJSON(key){try{return JSON.parse(localStorage.getItem(key));}catch{return null;}}
function writeJSON(key,value){try{localStorage.setItem(key,encode(value));}catch{toast('保存容量が足りません。記録を書き出してください');}}
function seedHash(s){let h=2166136261;for(const c of s){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return h>>>0;}
function initRandom(seed){rngDeal=seedHash('deal:'+seed);rngRescue=seedHash('rescue:'+seed);}
function dealRandom(){rngDeal=(Math.imul(rngDeal,1664525)+1013904223)>>>0;return rngDeal/4294967296;}
function rescueRandom(){rngRescue=(Math.imul(rngRescue,1664525)+1013904223)>>>0;return rngRescue/4294967296;}
function newSeed(){const a=new Uint32Array(2);crypto.getRandomValues(a);return [...a].map(v=>v.toString(36)).join('-').toUpperCase();}
function competitive(){return run.mode!=='normal';}
function elapsed(){return run.elapsed+(run.status==='playing'&&competitive()?Math.max(0,performance.now()-startedMono):0);}
function duration(ms){const sec=Math.floor(ms/1000),minutes=Math.floor(sec/60);return `${String(minutes).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}.${String(Math.floor(ms%1000/10)).padStart(2,'0')}`;}
function inputAllowed(){if(run.status!=='playing')return false;if(run.mode==='rogue'&&run.rogue.phase!=='play')return false;const limit=modes[run.mode]?.limit;if(limit&&elapsed()>=limit){if(!busy)finishRun('complete',limit);return false;}return true;}
function snapshot(){return {board:board.map(String),specials:[...specials],score:String(score),best:String(best),energy,fever,rngDeal,rngRescue,run:{...run,elapsed:elapsed(),savedAt:Date.now()}};}
function validBoard(s){return s&&Array.isArray(s.board)&&s.board.length===N&&s.board.every(v=>/^\d{1,1000}$/.test(String(v))&&BigInt(v)>=2n&&(BigInt(v)&(BigInt(v)-1n))===0n);}
function applySnapshot(s){if(!validBoard(s))throw Error('盤面形式が不正');board=s.board.map(BigInt);specials=Array.from({length:N},(_,i)=>['bomb','rainbow'].includes(s.specials?.[i])?s.specials[i]:null);score=BigInt(s.score||0);best=BigInt(s.best||0);energy=Number(s.energy)||0;fever=Number(s.fever)||0;rngDeal=s.rngDeal>>>0;rngRescue=s.rngRescue>>>0;run={...s.run,actions:s.run?.actions||[]};pendingFinish=run.status==='finishing';if(!modes[run.mode])throw Error('モード不正');if(run.mode==='rogue')validateRogue(run.rogue);startedMono=performance.now();path=[];previous=null;}
function persistGame(){if(!board.length)return;const current=busy&&moveCheckpoint?moveCheckpoint:snapshot();if(!competitive())normalSave=current;if(run.mode==='rogue')rogueSave=current;writeJSON(STATE_KEY,{version:2,current,normal:normalSave,rogue:rogueSave});}
function restoreGame(){records=readJSON(RECORDS_KEY)||[];if(!Array.isArray(records))records=[];const s=readJSON(STATE_KEY);try{if(s?.current){normalSave=s.normal;rogueSave=s.rogue||null;applySnapshot(s.current);if(competitive()&&run.mode!=='rogue'&&run.status==='playing'){run.elapsed+=Math.max(0,Date.now()-(s.current.run.savedAt||Date.now()));}render();updateRunUI();settleRun();return;}const legacy=readJSON(KEY);if(validBoard(legacy)){normalSave=null;applySnapshot({...legacy,score:String(legacy.score),best:String(legacy.best),rngDeal:seedHash('legacy-deal'),rngRescue:seedHash('legacy-rescue'),run:{mode:'normal',seed:'LEGACY',moves:0,actions:[],elapsed:0,status:'playing'}});render();updateRunUI();save();return;}}catch(e){console.warn('Saved game could not be restored',e);}startGame('normal',newSeed(),false);}
function startGame(mode,seed,abandon=true){if(busy)return;if(abandon&&competitive()&&run.status==='playing'&&(run.mode!=='rogue'||mode==='rogue'))finishRun('abandoned',elapsed(),false);if(run.mode==='rogue'&&board.length)rogueSave=snapshot();if(board.length&&!competitive())normalSave=snapshot();run={mode,seed:seed.trim().slice(0,40)||newSeed(),moves:0,actions:[],status:'playing',elapsed:0,startedAt:new Date().toISOString(),id:'run-'+newSeed()+'-'+Date.now().toString(36)};initRandom(run.seed);if(mode==='rogue')run.rogue=createRogue(run.seed);startedMono=performance.now();fresh();updateRunUI();}
function openSetup(){if(busy)return;$('modeSelect').value=run.mode;$('seedInput').value=run.seed==='LEGACY'?'':run.seed;$('resumeNormal').disabled=!normalSave||!competitive();if($('resumeRogue'))$('resumeRogue').disabled=!rogueSave||rogueSave.run.status!=='playing'||run.mode==='rogue';$('setupDialog').showModal();}
function updateRunUI(){$('modeButton').textContent=modes[run.mode].name+' ▾';const completed=records.filter(r=>r.mode===run.mode&&r.status==='complete'&&r.rules===RULES);const bestLabel=document.querySelector('.scorebox.best .label');if(bestLabel)bestLabel.textContent=competitive()?'MODE BEST ↗':'PERSONAL BEST ↗';if(competitive()){if(modes[run.mode].limit||run.mode==='rogue')showScore('best',completed.reduce((v,r)=>BigInt(r.score)>v?BigInt(r.score):v,0n));else{$('best').textContent=completed.length?duration(Math.min(...completed.map(r=>r.elapsed))):'—';$('best').title='この種目の最短時間';}}else showScore('best',best);$('seedButton').textContent='SEED '+run.seed;const ms=elapsed(),m=modes[run.mode];$('clock').textContent=!competitive()?'∞':duration(m.limit?Math.max(0,m.limit-ms):ms);$('clock').classList.toggle('timer-ended',run.status!=='playing');$('runState').textContent=run.status==='complete'?'FINISH':run.status==='abandoned'?'途中終了':!competitive()?'FREE PLAY':m.target?'目標 '+formatTile(1n<<BigInt(m.target)):'残り時間';$('undo').disabled=busy||!previous||competitive();$('hint').disabled=busy||competitive();if(typeof updateRogueUI==='function')updateRogueUI();}
function checkTarget(value,at){const target=modes[run.mode].target;if(competitive()&&run.status==='playing'&&target&&value>=(1n<<BigInt(target))){run.status='finishing';run.elapsed=at;pendingFinish=true;}}
function settleRun(){if(run.mode==='rogue'){rogueSettle();updateRunUI();return;}if(pendingFinish){pendingFinish=false;finishRun('complete',run.elapsed);return;}if(competitive()&&run.status==='playing'&&modes[run.mode].limit&&elapsed()>=modes[run.mode].limit)finishRun('complete',modes[run.mode].limit);updateRunUI();}
function cleanRecord(r){if(!r||!modes[r.mode]||r.mode==='normal'||r.rules!==RULES||typeof r.id!=='string'||r.id.length>100||typeof r.seed!=='string'||r.seed.length>40||!/^\d{1,1000}$/.test(r.score)||!Number.isFinite(r.elapsed)||r.elapsed<0||!Number.isInteger(r.maxExponent)||r.maxExponent<1||!Number.isInteger(r.moves)||r.moves<0||!['complete','abandoned'].includes(r.status))return null;return {id:r.id,mode:r.mode,rules:r.rules,seed:r.seed,score:r.score,elapsed:r.elapsed,maxExponent:r.maxExponent,moves:r.moves,status:r.status,endedAt:String(r.endedAt||'').slice(0,40),startedAt:String(r.startedAt||'').slice(0,40)};}
function finishRun(status,ms,show=true){if(!competitive()||['complete','abandoned'].includes(run.status))return;run.elapsed=ms;run.status=status;path=[];dragging=false;const rec=cleanRecord({id:run.id,mode:run.mode,rules:RULES,seed:run.seed,score:String(score),elapsed:Math.round(ms),maxExponent:exponent(maxTile(board.filter((v,i)=>specials[i]!=='rainbow'))),moves:run.moves,status,endedAt:new Date().toISOString(),startedAt:run.startedAt});if(rec&&!records.some(r=>r.id===rec.id)){records.push(rec);writeJSON(RECORDS_KEY,records);window.dispatchEvent(new CustomEvent('record-added',{detail:rec}));}render();updateRunUI();save();if(show){$('finishTitle').textContent=run.mode==='rogue'?(status==='complete'?'全10ステージ踏破！':'ラン終了'):status==='complete'?'FINISH!':'途中終了';$('runSummary').textContent=`${modes[run.mode].name}${run.mode==='rogue'?' / STAGE '+run.rogue.stage+' / 10':''}\nスコア ${score.toLocaleString('ja-JP')}\nタイム ${duration(ms)}\n最大 ${formatTile(1n<<BigInt(rec?.maxExponent||1))} / ${run.moves}手\nSEED ${run.seed}`;$('finishDialog').showModal();}}
function renderRecords(){let list=records.map(cleanRecord).filter(Boolean).filter(r=>($('historyMode').value==='all'||r.mode===$('historyMode').value)&&(!$('sameSeed').checked||r.seed===run.seed));if(recordTab==='ranking'){list=list.filter(r=>r.status==='complete');list.sort((a,b)=>a.mode.localeCompare(b.mode)||((modes[a.mode].limit||a.mode==='rogue')?(BigInt(a.score)>BigInt(b.score)?-1:BigInt(a.score)<BigInt(b.score)?1:a.elapsed-b.elapsed):a.elapsed-b.elapsed));}else list.sort((a,b)=>b.endedAt.localeCompare(a.endedAt));$('recordCount').textContent=`${list.length}件 · ${RULES} · ${recordTab==='ranking'?'完走のみ／種目ごとに比較／自己申告記録':'途中終了を含む'} · クラウド同期は自分の記録のみ`;$('historyRows').replaceChildren();for(const r of list){const tr=document.createElement('tr');const date=new Date(r.endedAt);const contents=[`${Number.isNaN(+date)?'—':date.toLocaleString('ja-JP')}\n${modes[r.mode].name}`,`${r.status==='abandoned'?'未達 / ':''}${modes[r.mode].limit||r.mode==='rogue'?formatScore(r.score):duration(r.elapsed)}`,`${formatTile(1n<<BigInt(r.maxExponent))} / ${r.moves}手`];for(const content of contents){const td=document.createElement('td');td.textContent=content;td.style.whiteSpace='pre-line';tr.append(td);}const td=document.createElement('td'),button=document.createElement('button');button.textContent=r.seed;button.title='同じ条件で再挑戦';button.onclick=()=>{if(busy){toast('落下が終わってから再挑戦できます');return;}$('historyDialog').close();$('modeSelect').value=r.mode;$('seedInput').value=r.seed;$('resumeNormal').disabled=!normalSave;$('setupDialog').showModal();};td.append(button);tr.append(td);$('historyRows').append(tr);}}
window.recordStore={get:()=>records.map(cleanRecord).filter(Boolean),merge(incoming){const map=new Map(records.map(r=>[r.id,r]));for(const raw of incoming){const r=cleanRecord(raw);if(r)map.set(r.id,r);}records=[...map.values()];writeJSON(RECORDS_KEY,records);if($('historyDialog').open)renderRecords();}};
$('modeButton').onclick=openSetup;$('seedButton').onclick=async()=>{try{await navigator.clipboard.writeText(run.seed);toast('シードをコピーしました');}catch{toast('SEED: '+run.seed);}};
$('closeSetup').onclick=()=>$('setupDialog').close();$('randomStart').onclick=()=>{if(busy)return;startGame($('modeSelect').value,newSeed());$('seedInput').value=run.seed;$('setupDialog').close();};$('startRun').onclick=()=>{startGame($('modeSelect').value,$('seedInput').value);$('setupDialog').close();};$('resumeNormal').onclick=()=>{if(busy||!normalSave)return;if(run.mode==='rogue')rogueSave=snapshot();else if(competitive()&&run.status==='playing')finishRun('abandoned',elapsed(),false);const keepBest=best;applySnapshot(normalSave);best=best>keepBest?best:keepBest;render();updateRunUI();save();$('setupDialog').close();};
$('historyButton').onclick=()=>{renderRecords();$('historyDialog').showModal();};$('closeHistory').onclick=()=>$('historyDialog').close();$('historyTab').onclick=()=>{recordTab='history';renderRecords();};$('rankingTab').onclick=()=>{recordTab='ranking';renderRecords();};$('historyMode').onchange=renderRecords;$('sameSeed').onchange=renderRecords;
$('finishClose').onclick=()=>$('finishDialog').close();$('finishRecords').onclick=()=>{$('finishDialog').close();renderRecords();$('historyDialog').showModal();};$('retryRun').onclick=()=>{if(busy)return;$('finishDialog').close();startGame(run.mode,run.seed);};
$('exportRecords').onclick=()=>{const blob=new Blob([encode({version:2,rules:RULES,records:window.recordStore.get()})],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='overdrive-records-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('importRecords').onclick=()=>$('importFile').click();$('importFile').onchange=async()=>{try{const file=$('importFile').files[0];if(!file)return;if(file.size>10*1024*1024)throw Error();const data=JSON.parse(await file.text());if(data.version!==2||!Array.isArray(data.records)||data.records.some(r=>!cleanRecord(r)))throw Error();window.recordStore.merge(data.records);renderRecords();toast('記録を読み込みました');window.dispatchEvent(new Event('records-imported'));}catch{toast('対応する記録ファイルを選んでください');}$('importFile').value='';};
window.addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{if(document.hidden){dragging=false;path=[];save();}else{settleRun();render();}});setInterval(()=>{if(!busy)settleRun();updateRunUI();},100);setInterval(()=>{if(competitive()&&run.status==='playing')save();},5000);

